:host {
  --desk-bg: #F8F9FB;
  --desk-surface: #FFFFFF;
  --desk-border: #DDE3EC;
  --desk-control-border: #596579;
  --desk-text: #202124;
  --desk-muted: #596579;
  --desk-primary: #1A56B8;
  --desk-primary-hover: #164A9D;
  --desk-primary-light: #E8F0FE;
  --desk-success: #188038;
  --desk-success-light: #E6F4EA;
  --desk-warning: #B42318;
  --desk-warning-light: #FCE8E6;
  --desk-font: 'Noto Sans Thai', system-ui, sans-serif;
  color-scheme: light;
} * {box-sizing:border-box} button,input {font:inherit} button {cursor:pointer} :host {font-family:var(--desk-font);font-size:14px;color:var(--desk-text)} button:focus-visible,input:focus-visible {outline:2px solid var(--desk-primary);outline-offset:3px} 
.desk-button { min-height: 44px; padding: 10px 17px; display: inline-flex; gap: 8px; align-items: center; justify-content: center; border-radius: 6px; font-weight: 600; font-size: 14px; line-height: 22px; border: 1px solid transparent; } 
.desk-button-primary { color: var(--desk-surface); background: var(--desk-primary); } 
.desk-button-primary:hover:not(:disabled) { background: var(--desk-primary-hover); } 
.desk-button-in { color: var(--desk-success); background: var(--desk-surface); border-color: var(--desk-border); } 
.desk-button-in:hover { background: var(--desk-success-light); } 
.desk-button:active:not(:disabled) { transform: translateY(1px); } 
.desk-button:disabled { background: var(--desk-border); color: var(--desk-muted); } 
.notification-item .desk-button { width: 100%; } 
.login-form > .desk-button { width: 100%; margin-top: 12px; } 
  .desk-actions .desk-button { flex: 1; padding-left: 8px; padding-right: 8px; } 
  .desk-button:active:not(:disabled) { transform: none; }

